import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { removeDiscussionFile } from "../handlers/removeDiscussionFile";
import type { ApiError } from "../runtime/client";
import type { RemoveDiscussionFileRequest } from "../types/RemoveDiscussionFileRequest";
import type { SpacePartition } from "../types/SpacePartition";
import type { SpacePostEntityType } from "../types/SpacePostEntityType";

type Data = Awaited<ReturnType<typeof removeDiscussionFile>>;
type Vars = { spaceId: SpacePartition; discussionId: SpacePostEntityType; req: RemoveDiscussionFileRequest };

export function useRemoveDiscussionFile(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => removeDiscussionFile(vars.spaceId, vars.discussionId, vars.req),
    ...options,
  });
}
